// Some portions generated by Codex
import type { CollectionAnalysis, CollectionCard, CollectionPreviewItem } from "./graph-collections.ts";

/** Internal suffixes are inspectable, but only maximal heads (and rdf:nil) have a canvas presentation toggle. */
export function canToggleCollectionView(analysis: CollectionAnalysis, headId: string) {
  const info = analysis.collections.get(headId);
  return Boolean(info?.collapsible && (analysis.heads.has(headId) || info.count === 0));
}

/** Shared by the SVG card, large-graph labels and exported images. */
export function collectionSummary(collection: Pick<CollectionCard, "count" | "loadedCount" | "title">) {
  if (collection.count === 0) return "Empty list";
  if (collection.count !== null) {
    const title = collection.title?.replace(/^./u, letter => letter.toLocaleUpperCase()) || "List";
    return `${title} · ${collection.count.toLocaleString()} ${collection.count === 1 ? "item" : "items"}`;
  }
  return `List · ${collection.loadedCount.toLocaleString()} loaded`;
}

export function collectionFooter(collection: CollectionCard): string | null {
  if (collection.status === "cycle") return "Cycle in list structure";
  if (collection.status === "ambiguous") return "Ambiguous list structure";
  if (collection.status === "partial") return "Continuation not loaded";
  return collection.hiddenCount > 0 ? `${collection.hiddenCount.toLocaleString()}${collection.preview.length ? " more" : ""} in details` : null;
}

/** Literal quotes distinguish values from resource labels without adding separate graph nodes. */
export function collectionMemberLabel(member: CollectionPreviewItem) {
  return member.kind === "literal" ? `"${member.label}"` : member.label;
}

export function collectionMemberTitle(member: CollectionPreviewItem) {
  const label = collectionMemberLabel(member);
  if (member.kind !== "literal") return `${label}\n${member.memberId}`;
  if (member.language) return `${label}@${member.language}${member.direction ? `--${member.direction}` : ""}`;
  return member.datatype ? `${label}^^${member.datatype}` : label;
}

export const COLLECTION_HEADER_HEIGHT = 40;
export const COLLECTION_ROW_HEIGHT = 52;
export const COLLECTION_MEMBER_LEFT = 43;
export const COLLECTION_FOOTER_HEIGHT = 24;

export const COLLECTION_DETAILS_ROW_HEIGHT = 52;
export const COLLECTION_DETAILS_VIEW_HEIGHT = 260;
const COLLECTION_DETAILS_OVERSCAN = 3;

/** Only the selected list is materialized; its inspector mounts a small window of occurrences. */
export function collectionMemberWindow(count: number, scrollTop: number) {
  const visible = Math.ceil(COLLECTION_DETAILS_VIEW_HEIGHT / COLLECTION_DETAILS_ROW_HEIGHT);
  const first = Math.min(Math.max(0, count - visible), Math.floor(Math.max(0, scrollTop) / COLLECTION_DETAILS_ROW_HEIGHT));
  return {
    start: Math.max(0, first - COLLECTION_DETAILS_OVERSCAN),
    end: Math.min(count, first + visible + COLLECTION_DETAILS_OVERSCAN),
  };
}
